use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    // To minimize memory usage, build the hash set from the smaller array.
    if a.len() < b.len() {
        let set: HashSet<i32> = a.into_iter().collect();
        for x in b {
            if set.contains(&x) {
                return true;
            }
        }
    } else {
        let set: HashSet<i32> = b.into_iter().collect();
        for x in a {
            if set.contains(&x) {
                return true;
            }
        }
    }
    false
}

// Example usage and simple tests
fn main() {
    let a = vec![1, 2, 3, 4];
    let b = vec![5, 6, 3, 8];
    assert!(has_common_element(a.clone(), b.clone())); // share '3'

    let c: Vec<i32> = vec![];
    let d = vec![1, 2, 3];
    assert!(!has_common_element(c.clone(), d.clone())); // one is empty

    let e = vec![10, 20, 30];
    let f = vec![40, 50, 60];
    assert!(!has_common_element(e.clone(), f.clone())); // no common elements

    println!("All tests passed!");
}